# ──────────────────────────────────────────────────────────────────────────
# 西南财大 live 首验（spec #25 / ticket #42）
# 只采集非密值与证据路径；模型 Key / Agent 凭据一律在网页里输入，不写 .env。
# ──────────────────────────────────────────────────────────────────────────

REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ENV_FILE="$REPO_ROOT/.live-acceptance-swufe.env"
ACCEPT_DIR=""
EVIDENCE="$REPO_ROOT/docs/acceptance/24-swufe/evidence"
MANIFEST="$REPO_ROOT/docs/acceptance/24-swufe/manifest.json"
README_FILE="$REPO_ROOT/docs/acceptance/24-swufe/README.md"
VERIFY="$REPO_ROOT/docs/acceptance/24-swufe/verify-evidence.mjs"
TASKS_DIR=""
SERVER_PID=""
mkdir -p "$EVIDENCE"

sha256_file() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{print $1}'
  else
    node --input-type=module -e 'import {createHash} from "node:crypto"; import fs from "node:fs"; console.log(createHash("sha256").update(fs.readFileSync(process.argv[1])).digest("hex"))' "$1"
  fi
}
db_hash_json() { node "$VERIFY" --hash-db "$1"; }
db_field() {
  printf '%s' "$1" | node --input-type=module -e 'import fs from "node:fs"; const d=JSON.parse(fs.readFileSync(0,"utf8")); process.stdout.write(String(d[process.argv[1]] ?? ""))' "$2"
}
snapshot_db() {
  local src="$1" dest="$2"
  [ -f "$src" ] || { warn "找不到 DB：$src"; return 1; }
  node --input-type=module -e 'import {DatabaseSync} from "node:sqlite"; const db=new DatabaseSync(process.argv[1]); db.exec("PRAGMA wal_checkpoint(TRUNCATE)"); db.close();' "$src"
  cp "$src" "$dest"
  note "snapshot → $dest"
}
task_latest() {
  node --input-type=module -e '
    import fs from "node:fs"; import path from "node:path";
    const dir = process.argv[1], exclude = process.argv[2] || "";
    let files = [];
    try { files = fs.readdirSync(dir).filter(f => f.endsWith(".json")); } catch { process.exit(0); }
    const tasks = files.map(f => { try { return JSON.parse(fs.readFileSync(path.join(dir, f), "utf8")); } catch { return null; } })
      .filter(t => t && String(t.title || "").startsWith("来源校对") && t.id !== exclude)
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
    const t = tasks[0];
    if (t) console.log(t.id + "	" + t.state + "	" + (t.phase || ""));
  ' "$TASKS_DIR" "$1"
}
task_field() {
  node --input-type=module -e 'import fs from "node:fs"; const t=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); const v=t[process.argv[2]]; console.log(typeof v==="number"?v:(v??""))' "$1" "$2"
}
wait_for_task() {
  local exclude="$1" deadline=$((SECONDS + 900)) info id state phase
  while (( SECONDS < deadline )); do
    info=$(task_latest "$exclude" || true)
    if [ -n "$info" ]; then
      IFS=$'\t' read -r id state phase <<< "$info"
      printf '  %s\n' "任务 $id · $state · $phase" >&2
      if [ "$state" = "succeeded" ] || [ "$state" = "failed" ] || [ "$state" = "blocked" ] || [ "$state" = "cancelled" ]; then
        printf '%s' "$info"; return 0
      fi
    fi
    sleep 5
  done
  return 1
}
wait_health() {
  local i
  for i in $(seq 1 60); do
    if curl -fsS "http://127.0.0.1:$PORT/health" >/dev/null 2>&1; then return 0; fi
    sleep 1
  done
  return 1
}
ensure_file() {
  local file="$1" label="$2"
  while [ ! -s "$file" ]; do
    warn "缺少 $label：$file"
    open_url "http://127.0.0.1:$PORT/chat"
    pause "保存/复制到上述路径后按 Enter 重试"
  done
}

TOTAL_STAGES=9

banner "西南财大双选会 live 首验"

# ── Stage 1: 准备隔离实例 ─────────────────────────────────────────────────
stage "准备：空的临时数据目录 + 启动服务"
say "不改真实数据；用独立的 CAREER_DATA_DIR。"
ask ACCEPT_DIR "临时数据目录（默认 $HOME/.career-agent-live/24-swufe）："
[ -n "$ACCEPT_DIR" ] || ACCEPT_DIR="$HOME/.career-agent-live/24-swufe"
case "$ACCEPT_DIR" in /*) ;; *) ACCEPT_DIR="$REPO_ROOT/$ACCEPT_DIR" ;; esac
mkdir -p "$ACCEPT_DIR"
ACCEPT_DIR="$(cd "$ACCEPT_DIR" && pwd)"
ACCEPT_DIR_WIN="$(cygpath -w "$ACCEPT_DIR" 2>/dev/null || printf '%s' "$ACCEPT_DIR")"
ask PORT "端口（默认 4189）："
[ -n "$PORT" ] || PORT=4189
write_env ACCEPT_DIR "$ACCEPT_DIR"
write_env ACCEPT_DIR_WIN "$ACCEPT_DIR_WIN"
write_env PORT "$PORT"

if curl -fsS "http://127.0.0.1:$PORT/health" >/dev/null 2>&1; then
