( cd "$REPO_ROOT" && CAREER_DATA_DIR="$ACCEPT_DIR" CAREER_HOST=127.0.0.1 PORT="$PORT" npm start > "$ACCEPT_DIR/server.log" 2>&1 & echo $! > "$ACCEPT_DIR/server.pid" )
