fi
open_url "http://127.0.0.1:$PORT/chat"
step "在页面登录 owner（推荐）或注册一个独立验收账号（密码只存在本机）。"
note "owner 账号与初始密码在 $ACCEPT_DIR/首次登录.txt；新注册账号不是 owner，不能用 stdio/Codex。"
pause "登录完成、看到聊天页后按 Enter"

USERS_ROOT="$ACCEPT_DIR/users"
USER_COUNT=$(find "$USERS_ROOT" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | wc -l | tr -d ' ')
if [ "$USER_COUNT" = "0" ]; then warn "没有找到 users/<id>；注册没有完成？"; exit 1; fi
USER_ID="$(basename "$(ls -1dt "$USERS_ROOT"/*/ 2>/dev/null | head -n1)")"
if [ "$USER_COUNT" != "1" ]; then
  warn "发现多个账号；请按账号名选择你刚登录的那个："
  node --input-type=module -e 'import fs from "node:fs"; const a=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); for(const u of a) console.log("  "+u.name+"  "+u.id);' "$ACCEPT_DIR/accounts.json"
  ask LOGIN_NAME "账号名（例如 owner）："
  USER_ID="$(node --input-type=module -e 'import fs from "node:fs"; const a=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); const u=a.find(x=>x.name===process.argv[2]); console.log(u?u.id:"");' "$ACCEPT_DIR/accounts.json" "$LOGIN_NAME")"
  [ -n "$USER_ID" ] || { warn "accounts.json 里没有账号 $LOGIN_NAME"; exit 1; }
fi
TASKS_DIR="$ACCEPT_DIR/users/$USER_ID/tasks"
DB="$ACCEPT_DIR/users/$USER_ID/.data/recruit.db"
write_env USER_ID "$USER_ID"
write_env DB "$DB"
say "验收账号：$USER_ID"
say "DB：$DB"

# ── Stage 2: 模型 ─────────────────────────────────────────────────────────
stage "配置视觉模型与文本后端"
open_url "http://127.0.0.1:$PORT/chat"
