# ── Stage 6: 干净撤销 ─────────────────────────────────────────────────────
stage "干净用例：任务级撤销 → 撤销后快照"
step "抽屉任务卡 →「查看审计明细」→「撤销本任务全部自动写入」→ 确认。"
step "等待「已撤销 N」；不要触发强制撤销。"
pause "撤销完成、任务卡显示已撤销后按 Enter"
snapshot_db "$DB" "$EVIDENCE/recruit.db.after-undo"
UNDO_SHA="$(sha256_file "$EVIDENCE/recruit.db.after-undo")"
UNDO_JSON="$(db_hash_json "$EVIDENCE/recruit.db.after-undo")"
UNDO_HASH="$(db_field "$UNDO_JSON" hash)"
UNDO_EVENTS="$(db_field "$UNDO_JSON" events)"
UNDO_PROJECTS="$(db_field "$UNDO_JSON" projects)"
write_env UNDO_SHA "$UNDO_SHA"; write_env UNDO_HASH "$UNDO_HASH"
write_env UNDO_EVENTS "$UNDO_EVENTS"; write_env UNDO_PROJECTS "$UNDO_PROJECTS"
if [ "$UNDO_HASH" = "$BEFORE_HASH" ] && [ "$UNDO_EVENTS" = "$BEFORE_EVENTS" ] && [ "$UNDO_PROJECTS" = "$BEFORE_PROJECTS" ]; then
  UNDO_CLEAN="true"; say "✓ 干净撤销与验收前快照一致"
else
  UNDO_CLEAN="false"; warn "撤销后与验收前不一致：before=$(printf '%s' "$BEFORE_HASH" | cut -c1-12)… after-undo=$(printf '%s' "$UNDO_HASH" | cut -c1-12)…"
fi
write_env UNDO_CLEAN "$UNDO_CLEAN"

# ── Stage 7: 冲突用例 ─────────────────────────────────────────────────────
stage "冲突用例：第二次写库 + 手工改 1 行（不产生审计）"
open_url "http://127.0.0.1:$PORT/recruit"
step "再做一次「来源校对」并等待任务成功；这是冲突用例，taskId 会与干净用例不同。"
pause "第二次任务成功后按 Enter"
CONFLICT_INFO="$(wait_for_task "$TASK_ID" || true)"
[ -n "$CONFLICT_INFO" ] || { warn "没有找到第二张来源校对任务"; exit 1; }
IFS=$'\t' read -r CONFLICT_TASK_ID CONFLICT_STATE CONFLICT_PHASE <<< "$CONFLICT_INFO"
[ "$CONFLICT_STATE" = "succeeded" ] || { warn "冲突用例任务状态是 $CONFLICT_STATE（$CONFLICT_PHASE）"; exit 1; }
write_env CONFLICT_TASK_ID "$CONFLICT_TASK_ID"
say "conflict task: $CONFLICT_TASK_ID"
step "现在手工改 1 行 event_projects.title；下面的 out-of-band 命令不走写网关，因此不产生审计。"
pause "准备改行时按 Enter"
node --input-type=module - "$DB" <<'NODE'
import {DatabaseSync} from 'node:sqlite';
const db = new DatabaseSync(process.argv[2]);
const row = db.prepare("SELECT id, event_id, title FROM event_projects WHERE status='active' ORDER BY created_at DESC LIMIT 1").get();
if (!row) { console.error('没有可改的 event_projects 行'); process.exit(1); }
const next = String(row.title || '未填') + '（手工核对）';
db.prepare('UPDATE event_projects SET title=? WHERE id=?').run(next, row.id);
console.log('手工改写:', row.id, JSON.stringify(row.title), '→', JSON.stringify(next));
db.close();
NODE
CONFLICT_PROJECT_ID="$(node --input-type=module -e 'import {DatabaseSync} from "node:sqlite"; const db=new DatabaseSync(process.argv[1]); const r=db.prepare("SELECT id FROM event_projects WHERE title LIKE ? ORDER BY created_at DESC LIMIT 1").get("%（手工核对）"); console.log(r?r.id:""); db.close();' "$DB")"
write_env CONFLICT_PROJECT_ID "$CONFLICT_PROJECT_ID"
step "回到抽屉 → 冲突任务的「查看审计明细」→「撤销本任务全部自动写入」；应显示「已撤销 N-1 / 冲突 1」。"
step "在点「强制撤销」之前，截图二次确认弹窗保存为：$EVIDENCE/ui-force-confirm.png"
ensure_file "$EVIDENCE/ui-force-confirm.png" "强制撤销确认截图"
step "点「强制撤销并覆盖」→ 等待结果；审计应同时出现 skip 与 forced。"
pause "强制撤销完成后按 Enter"
step "审阅层「全部审计」→「导出 JSON」→ 覆盖保存为：$EVIDENCE/audit-export.json"
ensure_file "$EVIDENCE/audit-export.json" "审计导出（含 skip/forced）"

# ── Stage 8: 证据统计 ─────────────────────────────────────────────────────
stage "核对证据与计数"
ensure_file "$EVIDENCE/extraction.json" "抽取 JSON"
ensure_file "$EVIDENCE/review.json" "复核 JSON"
ensure_file "$EVIDENCE/task.json" "任务日志"
ensure_file "$EVIDENCE/recruit.db.before" "DB before"
ensure_file "$EVIDENCE/recruit.db.after" "DB after"
ensure_file "$EVIDENCE/recruit.db.after-undo" "DB after-undo"
ensure_file "$TASK_EVIDENCE/01-list.png" "截图 1 列表页"
ensure_file "$TASK_EVIDENCE/02-detail.png" "截图 2 详情页"

BROWSER_READS="$(node --input-type=module -e 'import fs from "node:fs"; try{const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); console.log(Array.isArray(d)?d.length:0)}catch{console.log(0)}' "$EVIDENCE/screenshots.json")"
TASK_DURATION="$(task_field "$TASK_JSON" durationMs)"
REVIEW_ISSUES="$(node --input-type=module -e 'import fs from "node:fs"; try{const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); console.log(Array.isArray(d)?d.length:(Array.isArray(d.issues)?d.issues.length:0))}catch{console.log(0)}' "$EVIDENCE/review.json")"
REVIEW_STATUS="$(node --input-type=module -e 'import fs from "node:fs"; try{const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); console.log((d && typeof d==="object" && !Array.isArray(d)) ? (d.status || (d.error ? "unavailable" : "ok")) : "ok")}catch{console.log("unavailable")}' "$EVIDENCE/review.json")"
if [ "$REVIEW_STATUS" = "unavailable" ]; then warn "复核不可用（review.status=unavailable）；按规格这一项未通过，不能签。先修 Agent 后重跑 clean 用例。"; exit 1; fi
write_env REVIEW_STATUS "$REVIEW_STATUS"
AUDIT_STATS="$(node --input-type=module -e 'import fs from "node:fs"; const d=JSON.parse(fs.readFileSync(process.argv[1],"utf8")); const rows=(d.batches||[]).flatMap(b=>b.rows||[]); console.log(rows.length+" "+(rows.filter(r=>r.result==="skipped_conflict").length)+" "+(rows.filter(r=>r.result==="forced").length));' "$EVIDENCE/audit-export.json")"
read -r AUDIT_ROWS AUDIT_SKIPPED AUDIT_FORCED <<< "$AUDIT_STATS"
[ -n "$AUDIT_ROWS" ] || AUDIT_ROWS=0
[ -n "$AUDIT_SKIPPED" ] || AUDIT_SKIPPED=0
[ -n "$AUDIT_FORCED" ] || AUDIT_FORCED=0
DUP_ROWS="$(node --input-type=module -e 'import {DatabaseSync} from "node:sqlite"; const db=new DatabaseSync(process.argv[1]); const e=db.prepare("SELECT title,start_at,COUNT(*) c FROM events GROUP BY title,start_at HAVING c>1").all(); const p=db.prepare("SELECT event_id,company,title,COUNT(*) c FROM event_projects GROUP BY event_id,company,title HAVING c>1").all(); console.log(e.length+p.length); db.close();' "$DB")"
COMPANY_DB="false"; [ -f "$ACCEPT_DIR/users/$USER_ID/.data/company.db" ] && COMPANY_DB="true"
write_env BROWSER_READS "$BROWSER_READS"; write_env TASK_DURATION "$TASK_DURATION"; write_env REVIEW_ISSUES "$REVIEW_ISSUES"
write_env AUDIT_ROWS "$AUDIT_ROWS"; write_env AUDIT_SKIPPED "$AUDIT_SKIPPED"; write_env AUDIT_FORCED "$AUDIT_FORCED"
write_env DUP_ROWS "$DUP_ROWS"; write_env COMPANY_DB "$COMPANY_DB"
say "browserReads=$BROWSER_READS  durationMs=$TASK_DURATION  auditRows=$AUDIT_ROWS"
say "conflictSkipped=$AUDIT_SKIPPED  forced=$AUDIT_FORCED  duplicateRows=$DUP_ROWS  companyDb=$COMPANY_DB"
say "reviewIssues=$REVIEW_ISSUES  undoClean=$UNDO_CLEAN"
warn "再确认一次：采集器 0 次、fetchText 直连 0 次、联系方式 0 条；任一项不成立就不要签。"
confirm "以上计数与边界都成立，继续填 manifest？" || { warn "未确认，停止在签字之前。"; exit 1; }

# ── Stage 9: 填 manifest、校验、签字 ──────────────────────────────────────
stage "填写 manifest → 校验 → README 签字"
ask OWNER_NAME "验收人姓名/账号："
[ -n "$OWNER_NAME" ] || { warn "验收人不能为空。"; exit 1; }
TODAY="$(date +%F)"
RUN_AT="$(date -Iseconds)"
[ -f "$MANIFEST" ] || cp "$REPO_ROOT/docs/acceptance/24-swufe/manifest.template.json" "$MANIFEST"
EXTRACTION_SHA="$(sha256_file "$EVIDENCE/extraction.json")"
REVIEW_SHA="$(sha256_file "$EVIDENCE/review.json")"
AUDIT_SHA="$(sha256_file "$EVIDENCE/audit-export.json")"
TASK_SHA="$(sha256_file "$EVIDENCE/task.json")"
LIST_SHA="$(sha256_file "$TASK_EVIDENCE/01-list.png")"
DETAIL_SHA="$(sha256_file "$TASK_EVIDENCE/02-detail.png")"
UI_TASK_SHA="$(sha256_file "$EVIDENCE/ui-task-card.png")"
UI_AUDIT_SHA="$(sha256_file "$EVIDENCE/ui-audit-review.png")"
UI_FORCE_SHA="$(sha256_file "$EVIDENCE/ui-force-confirm.png")"
BEFORE_DB_SHA="$(sha256_file "$EVIDENCE/recruit.db.before")"
AFTER_DB_SHA="$(sha256_file "$EVIDENCE/recruit.db.after")"
UNDO_DB_SHA="$(sha256_file "$EVIDENCE/recruit.db.after-undo")"
export MANIFEST EVIDENCE ACCEPT_DIR ACCEPT_DIR_WIN USER_ID TASK_ID CONFLICT_TASK_ID COMMIT NODE_VERSION EDGE_VERSION RUN_AT OWNER_NAME TODAY
export VISION_MODEL AGENT_NAME AGENT_REVIEW_TOOL BROWSER_READS TASK_DURATION REVIEW_ISSUES
export AUDIT_ROWS AUDIT_SKIPPED AUDIT_FORCED DUP_ROWS COMPANY_DB UNDO_CLEAN
export BEFORE_EVENTS BEFORE_PROJECTS UNDO_EVENTS UNDO_PROJECTS AFTER_EVENTS AFTER_PROJECTS AFTER_HASH BEFORE_HASH UNDO_HASH
export EXTRACTION_SHA REVIEW_SHA AUDIT_SHA TASK_SHA LIST_SHA DETAIL_SHA UI_TASK_SHA UI_AUDIT_SHA UI_FORCE_SHA
export BEFORE_DB_SHA AFTER_DB_SHA UNDO_DB_SHA

node --input-type=commonjs - "$MANIFEST" <<'NODE'
const fs = require('fs');
const p = process.argv[2];
const m = JSON.parse(fs.readFileSync(p, 'utf8'));
const env = process.env;
m.status = 'passed';
m.runAt = env.RUN_AT;
m.owner = env.OWNER_NAME;
m.environment = {dataDir: env.ACCEPT_DIR_WIN, userId: env.USER_ID, taskId: env.TASK_ID, conflictTaskId: env.CONFLICT_TASK_ID, commit: env.COMMIT, nodeVersion: env.NODE_VERSION, edgeVersion: env.EDGE_VERSION};
m.evidence = {
  extraction: {path: 'evidence/extraction.json', sha256: env.EXTRACTION_SHA},
  review: {path: 'evidence/review.json', sha256: env.REVIEW_SHA},
  auditExport: {path: 'evidence/audit-export.json', sha256: env.AUDIT_SHA},
  taskLog: {path: 'evidence/task.json', sha256: env.TASK_SHA},
  screenshots: {
    list: {path: env.ACCEPT_DIR_WIN + '/users/' + env.USER_ID + '/tasks/' + env.TASK_ID + '/evidence/01-list.png', sha256: env.LIST_SHA},
    detail: {path: env.ACCEPT_DIR_WIN + '/users/' + env.USER_ID + '/tasks/' + env.TASK_ID + '/evidence/02-detail.png', sha256: env.DETAIL_SHA},
    uiTaskCard: {path: 'evidence/ui-task-card.png', sha256: env.UI_TASK_SHA},
    uiAuditReview: {path: 'evidence/ui-audit-review.png', sha256: env.UI_AUDIT_SHA},
    uiForceConfirm: {path: 'evidence/ui-force-confirm.png', sha256: env.UI_FORCE_SHA}
  },
  db: {
    before: {path: 'evidence/recruit.db.before', sha256: env.BEFORE_DB_SHA, contentHash: env.BEFORE_HASH, events: Number(env.BEFORE_EVENTS), projects: Number(env.BEFORE_PROJECTS)},
    after: {path: 'evidence/recruit.db.after', sha256: env.AFTER_DB_SHA, contentHash: env.AFTER_HASH, events: Number(env.AFTER_EVENTS), projects: Number(env.AFTER_PROJECTS)},
    afterUndo: {path: 'evidence/recruit.db.after-undo', sha256: env.UNDO_DB_SHA, contentHash: env.UNDO_HASH, events: Number(env.UNDO_EVENTS), projects: Number(env.UNDO_PROJECTS)}
  }
};
m.checks = {browserReads: Number(env.BROWSER_READS), collectorRuns: 0, fetchTextCalls: 0, events: Number(env.AFTER_EVENTS), projects: Number(env.AFTER_PROJECTS), contactFields: 0, auditRows: Number(env.AUDIT_ROWS), auditDataRatio: '1:1', undoCleanMatchesBefore: env.UNDO_CLEAN === 'true', conflictSkipped: Number(env.AUDIT_SKIPPED), forced: Number(env.AUDIT_FORCED), companyDbCreated: env.COMPANY_DB === 'true', duplicateRows: Number(env.DUP_ROWS), durationMs: Number(env.TASK_DURATION)};
m.agentLeg = {passed: true, tool: env.AGENT_REVIEW_TOOL, issueCount: Number(env.REVIEW_ISSUES)};
m.signature = {statement: '验收通过', date: env.TODAY, name: env.OWNER_NAME};
fs.writeFileSync(p, JSON.stringify(m, null, 2) + '\n');
console.log('manifest 已填写：' + p);
NODE

set +e
node "$VERIFY" "$MANIFEST"
VERIFY_CODE=$?
set -e
if [ "$VERIFY_CODE" != "0" ]; then
  node --input-type=commonjs - "$MANIFEST" <<'NODE'
const fs = require('fs'); const p = process.argv[2]; const m = JSON.parse(fs.readFileSync(p, 'utf8'));
m.status = 'pending';
m.signature = {statement: '', date: '', name: ''};
fs.writeFileSync(p, JSON.stringify(m, null, 2) + '\n');
NODE
  warn "校验未通过（退出码 $VERIFY_CODE）。已把 manifest 状态退回 pending；修正证据后重新运行，不要签 README。"
  exit 1
fi
MANIFEST_SHA="$(sha256_file "$MANIFEST")"
confirm "证据包已通过校验，写入 README 签字区？" || { warn "未写入签字；manifest 已保留。"; exit 0; }
node --input-type=commonjs - "$README_FILE" "$TODAY" "$OWNER_NAME" "$MANIFEST_SHA" <<'NODE'
const fs = require('fs');
const p = process.argv[2], date = process.argv[3], name = process.argv[4], sha = process.argv[5];
let s = fs.readFileSync(p, 'utf8');
s = s.replace(/^- 结论：.*$/m, '- 结论：验收通过')
     .replace(/^- 日期：.*$/m, '- 日期：' + date)
     .replace(/^- 验收人：.*$/m, '- 验收人：' + name)
     .replace(/^- 证据清单：.*$/m, '- 证据清单：manifest.json sha256 ' + sha)
     .replace(/^- 备注：.*$/m, '- 备注：live 首验按本 README 执行；确定性回归 332 项通过，证据包校验通过。');
fs.writeFileSync(p, s);
console.log('README 签字区已写入');
NODE

finish
note "服务仍在后台运行（pid $SERVER_PID，日志 $ACCEPT_DIR/server.log）。"
note "证据目录：$EVIDENCE"
note "manifest：$MANIFEST"
note "下一步：git status docs/acceptance/24-swufe；确认无联系方式后提交证据包。"
note "最后到 spec #25 详情页点「完成」做收口核对。"
if confirm "现在停止本地验收服务？"; then
  taskkill //PID "$SERVER_PID" //T //F >/dev/null 2>&1 || kill "$SERVER_PID" 2>/dev/null || true
  note "已尝试停止服务 pid=$SERVER_PID"
fi
